/**
 * EzyCore Ai - Apps Script Connector
 * Minimal bridge for communication between Blogger SPA and Google Apps Script.
 */

(function () {
    // Helper untuk mendapatkan Gateway URL
    window.getGatewayUrl = () => {
        const getParam = (p) => {
            const sp = new URLSearchParams(window.location.search);
            if (sp.get(p)) return sp.get(p);
            if (window.location.hash.includes('?')) {
                const hp = new URLSearchParams(window.location.hash.split('?')[1]);
                return hp.get(p);
            }
            return null;
        };

        const urlFromParam = getParam('url') || getParam('userWebAppUrl') || window.BLOGGER_WEBAPP_URL;
        if (urlFromParam) return urlFromParam.trim();

        if (typeof getWebAppUrl === 'function') {
            const url = getWebAppUrl();
            if (url) return url.trim();
        }

        if (typeof CONFIG !== 'undefined' && CONFIG.WEBAPP_URL_DEV) {
            return CONFIG.WEBAPP_URL_DEV.trim();
        }
        return '';
    };

    // Inisialisasi State Global
    window.EzyApi = {
        url: '',
        role: window.EZY_ROLE || 'Public',
        isReady: false,
        config: { adminUrl: '', publicUrl: '', isSetup: true }
    };

    // 1. Initialize global Apps Script URL from LocalStorage
    const getStoredConfig = () => {
        const blogId = window.EZY_BLOG_ID || '';
        const storageKey = 'EzycoreConfig_' + blogId;
        try {
            let config = JSON.parse(localStorage.getItem(storageKey) || '{}');
            if (config.webappUrl && config.webappUrl.startsWith('https://script.google.com')) return config.webappUrl;

            const discoveryEl = document.getElementById('ezycore-discovery');
            if (discoveryEl && discoveryEl.dataset.config) {
                const decoded = JSON.parse(atob(discoveryEl.dataset.config));
                if (decoded.webappUrl && decoded.webappUrl.startsWith('https://script.google.com')) {
                    localStorage.setItem(storageKey, JSON.stringify(decoded));
                    return decoded.webappUrl;
                }
            }
            return '';
        } catch (e) {
            console.error('[EzyCore] Config discovery failed:', e);
            return '';
        }
    };

    const discoverEzyApi = async () => {
        if (window.EZY_DISCOVERY_PENDING) {
            console.log('Discovery: Paused (Waiting for SiteKey resolution)...');
            return;
        }

        const cacheKey = 'EzyCoreConfig_Cache';
        const HARDCODED_URL = (typeof CONFIG !== 'undefined' && CONFIG.WEBAPP_URL_DEV) ? CONFIG.WEBAPP_URL_DEV.trim() : '';
        let CURRENT_URL = getGatewayUrl();

        const cached = localStorage.getItem(cacheKey);
        if (cached) {
            try {
                const config = JSON.parse(cached);
                window.EzyApi.config = config;
                applyRoleUrl(config);
            } catch (e) {}
        }

        if (!CURRENT_URL) {
            console.warn('EzyCore Discovery: No URL found.');
            window.EzyApi.isReady = true;
            window.dispatchEvent(new CustomEvent('ezy-api-ready', { detail: window.EzyApi }));
            return;
        }

        const fetchConfig = async (targetUrl, action = 'get_config') => {
            const cbName = 'ezy_discovery_' + Date.now() + Math.floor(Math.random() * 100);
            const script = document.createElement('script');
            const separator = targetUrl.includes('?') ? '&' : '?';
            const finalUrl = `${targetUrl}${separator}action=${action}&callback=${cbName}`;

            // Guard: Only proceed if URL is valid
            if (!targetUrl || !targetUrl.startsWith('http')) {
                return Promise.reject(new Error('Invalid WebApp URL'));
            }

            script.src = finalUrl;

            return new Promise((resolve, reject) => {
                window[cbName] = (res) => {
                    delete window[cbName];
                    script.remove();
                    resolve(res);
                };
                script.onerror = () => {
                    script.remove();
                    reject(new Error('Script load failed'));
                };
                (document.head || document.documentElement).appendChild(script);
                setTimeout(() => { script.remove(); reject(new Error('Timeout after 30s')); }, 30000);
            });
        };

        try {
            let config;
            try {
                config = await fetchConfig(CURRENT_URL);
            } catch (e) {
                if (CURRENT_URL !== HARDCODED_URL && HARDCODED_URL) {
                    config = await fetchConfig(HARDCODED_URL);
                } else {
                    throw e;
                }
            }

            if (config && (config.status === 'success' || config.isSetup === false || config.statusNote === 'no_config')) {
                window.EzyApi.config = config;

                if (config.status === 'success' && config.isSetup === true && config.statusNote === 'active') {
                    localStorage.setItem(cacheKey, JSON.stringify(config));
                    applyRoleUrl(config);
                } else if (config.statusNote === 'setup_in_progress') {
                    applyRoleUrl(config);
                } else if (config.isGateway && config.statusNote === 'no_config') {
                    try {
                        const adminDiscovery = await fetchConfig(CURRENT_URL, 'get_admin_url');
                        if (adminDiscovery && adminDiscovery.status === 'success' && adminDiscovery.adminUrl) {
                            config.adminUrl = adminDiscovery.adminUrl;
                            config.isSetup = true;
                            localStorage.setItem(cacheKey, JSON.stringify(config));
                            applyRoleUrl(config);
                        }
                    } catch (err) {
                        console.warn('Secondary discovery failed:', err);
                    }
                }
            }
        } catch (e) {
            console.error('Discovery CRITICAL Error:', e.message);
            applyRoleUrl({});
        } finally {
            window.EzyApi.isReady = true;
            window.dispatchEvent(new CustomEvent('ezy-api-ready', { detail: window.EzyApi }));
        }
    };

    function applyRoleUrl(config) {
        config = config || {};
        const role = window.EzyApi.role;
        let DISCOVERY_URL = getGatewayUrl();

        if (!DISCOVERY_URL && typeof CONFIG !== 'undefined' && CONFIG.WEBAPP_URL_DEV) {
            DISCOVERY_URL = CONFIG.WEBAPP_URL_DEV.trim();
        }

        let targetUrl;
        if (role === 'Admin') {
            targetUrl = config.adminUrl || config.publicUrl || DISCOVERY_URL;
        } else {
            targetUrl = config.publicUrl || config.adminUrl || DISCOVERY_URL;
        }

        const finalUrl = (targetUrl && targetUrl.startsWith('http')) ? targetUrl.trim() : DISCOVERY_URL;

        window.EzyApi.url = finalUrl;
        window.EzyApi.gatewayUrl = DISCOVERY_URL;
        window.appsScriptUrl = finalUrl;

        if (window.app) {
            const isDbValid = config.isSetup !== false;
            const hasSiteKey = role === 'Public' ? !!config.siteKey : true;

            window.app.dbHealthy = isDbValid && hasSiteKey;
            window.app.dbStatusChecked = true;
        }
    }

    // Initialize URL immediately, then run discovery
    const storedUrl = getStoredConfig();
    window.appsScriptUrl = storedUrl;
    window.EzyApi.url = storedUrl;

    // Run discovery asynchronously
    discoverEzyApi();

    /**
     * Global function to send data to Google Apps Script Web App
     * @param {string} action - The action identifier
     * @param {object} data - The payload to send
     * @param {function} callback - Success handler
     * @param {function} errorCallback - Error handler
     * @param {string} overrideUrl - Optional URL to use instead of the configured one
     */
    window.sendDataToGoogle = function (action, data, callback, errorCallback, overrideUrl) {
        if (!window.EzyApi.isReady) {
            setTimeout(() => window.sendDataToGoogle(action, data, callback, errorCallback, overrideUrl), 300);
            return;
        }

        const postActions = [
            'SignInUser', 'registerUser', 'SignOut',
            'saveEvent', 'updateProfile', 'createProfile',
            'save_post', 'updateCoreProfile', 'updatePublicProfile', 'updateProfilePhoto',
            'uploadImageAndGetUrl', 'generateAiImage', 'setupUserDatabase',
            'save_plugin', 'remove_plugin', 'ping_plugin',
            'dbCreate', 'dbUpdate', 'dbDelete', 'createTable',
            'getEvents', 'createEvent', 'updateEvent', 'deleteEvent',
            'saveAiConfig', 'askAi', 'createAiRule', 'updateAiRule', 'deleteAiRule',
            'saveThemeSettings', 'save_settings',
            'getHotspotProjects', 'saveHotspotProject', 'deleteHotspotProject',
            'createTransaction', 'voidTransaction', 'saveSparepart', 'deleteSparepart', 'adjustStock',
            'savePurchaseOrder', 'deletePurchaseOrder', 'processReceiving', 'sendPOToSupplier', 'getMasterParts', 'saveMasterPart',
            'send_personal_message', 'receive_personal_message', 'mark_as_read',
            'saveLandingProduct', 'deleteLandingProduct',
            'saveAboutPage', 'saveContactPage', 'saveStaticPage',
            'get_post_by_slug',
            'saveAlbum', 'deleteAlbum', 'saveAlbumImage', 'deleteAlbumImage', 'syncAlbumMetadataToBlogger', 'setupPluginDatabase', 'savePublicContentSettings',
            'getExistingNotifications' // Notifications Actions
        ];

        if (postActions.includes(action)) {
            const payload = {
                action,
                dbId: data.dbId || (window.EzyApi.config ? window.EzyApi.config.dbId : ''),
                pluginContentDbId: data.pluginContentDbId || '',
                siteKey: data.siteKey || (window.EzyApi.config ? window.EzyApi.config.siteKey : ''),
                ...data,
                gatewayUrl: window.EzyApi.gatewayUrl
            };

            let targetUrl = overrideUrl || window.EzyApi.url;
            if (!targetUrl && typeof CONFIG !== 'undefined' && CONFIG.WEBAPP_URL_DEV) {
                console.warn('EzyApi.url is empty, using CONFIG fallback for POST');
                targetUrl = CONFIG.WEBAPP_URL_DEV;
            }

            console.log(`[sendDataToGoogle] POST ${action} to ${targetUrl}`, { payloadSize: JSON.stringify(payload).length });

            fetch(targetUrl, {
                method: 'POST',
                body: JSON.stringify(payload)
            })
                .then(res => {
                    console.log(`[sendDataToGoogle] Response status: ${res.status} for ${action}`);
                    if (!res.ok) throw new Error('Network response was not ok');
                    return res.json();
                })
                .then(callback)
                .catch(err => {
                    console.error(`[sendDataToGoogle] Error for ${action}:`, err);
                    if (errorCallback) errorCallback(err);
                });
        } else {
            const cbName = 'ezy_cb_' + Date.now() + Math.floor(Math.random() * 100);
            window[cbName] = function (res) {
                delete window[cbName];
                const s = document.getElementById(cbName);
                if (s) s.remove();
                if (callback) callback(res);
            };

            const baseUrl = overrideUrl || window.EzyApi.url;

            // Guard: Only proceed with valid WebApp URL
            if (!baseUrl || !baseUrl.startsWith('https://script.google.com')) {
                console.warn('[EzyCore] JSONP skipped: Invalid WebApp URL', baseUrl);
                if (errorCallback) errorCallback('URL_MISSING');
                return;
            }

            const query = new URLSearchParams({
                action,
                dbId: data.dbId || (window.EzyApi.config ? window.EzyApi.config.dbId : ''),
                pluginContentDbId: data.pluginContentDbId || '',
                siteKey: data.siteKey || (window.EzyApi.config ? window.EzyApi.config.siteKey : ''),
                callback: cbName,
                gatewayUrl: window.EzyApi.gatewayUrl || '',
                ...data
            }).toString();
            const script = document.createElement('script');
            script.id = cbName;
            const separator = baseUrl.includes('?') ? '&' : '?';
            script.src = `${baseUrl}${separator}${query}`;
            (document.head || document.documentElement).appendChild(script);
        }
    };
})();